<?php
declare(strict_types=1);
require_once __DIR__.'/_common.php';
$sponsorId=(int)($user['id']??0);
$ready=sponsor_table_exists($conn,'sponsor_documents')&&sponsor_table_exists($conn,'sponsor_document_versions')&&sponsor_table_exists($conn,'sponsor_document_programmes')&&sponsor_table_exists($conn,'sponsor_programme_access');
$category=trim((string)($_GET['category']??''));$search=trim((string)($_GET['q']??''));$documents=[];$categories=[];$error='';
if($ready){
 $categories=sponsor_rows($conn,"SELECT DISTINCT d.category FROM sponsor_documents d JOIN sponsor_document_programmes dp ON dp.document_id=d.id JOIN sponsor_programme_access a ON a.programme_id=dp.programme_id AND a.sponsor_user_id={$sponsorId} AND a.access_status='active' WHERE d.status='published' ORDER BY d.category");
 $sql="SELECT d.id,d.title,d.description,d.category,d.document_type,d.updated_at,d.created_at,COUNT(DISTINCT v.id) version_count,MAX(v.version_number) latest_version,MAX(v.published_at) latest_published, GROUP_CONCAT(DISTINCT p.name ORDER BY p.name SEPARATOR ', ') programme_names FROM sponsor_documents d JOIN sponsor_document_programmes dp ON dp.document_id=d.id JOIN sponsor_programme_access a ON a.programme_id=dp.programme_id AND a.sponsor_user_id=? AND a.access_status='active' JOIN programmes p ON p.id=dp.programme_id JOIN sponsor_document_versions v ON v.document_id=d.id AND v.status='published' WHERE d.status='published' AND (d.available_from IS NULL OR d.available_from<=NOW()) AND (d.available_until IS NULL OR d.available_until>=NOW())";
 $types='i';$params=[$sponsorId];if($category!==''){$sql.=' AND d.category=?';$types.='s';$params[]=$category;}if($search!==''){$sql.=' AND (d.title LIKE ? OR d.description LIKE ? OR p.name LIKE ?)';$types.='sss';$like='%'.$search.'%';array_push($params,$like,$like,$like);}
 $sql.=' GROUP BY d.id ORDER BY COALESCE(d.updated_at,d.created_at) DESC,d.id DESC';$st=$conn->prepare($sql);if($st){$st->bind_param($types,...$params);$st->execute();$rs=$st->get_result();$documents=$rs?$rs->fetch_all(MYSQLI_ASSOC):[];$st->close();}
}
sponsor_header('Sponsor document repository','documents','Access authorised programme documents, financial reports and performance updates with version history.');
?>
