mns:1fr}.sd-toolbar>*{width:100%}.sd-toolbar input,.sd-toolbar select{width:100%}}
</style>
<?php if(!$ready): ?><div class="sd-info"><strong>Repository setup required.</strong> Import <code>database/sponsor_document_repository_migration.sql</code> before using this page.</div><?php else: ?>
<div class="sd-info">Documents are visible only when published and linked to a programme assigned to your sponsor account. The repository displays the latest published version and retains prior version records.</div>
<form class="sd-toolbar" method="get"><label>Search documents<input type="search" name="q" value="<?= sponsor_e($search) ?>" placeholder="Search title, description or programme"></label><label>Document category<select name="category"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?= sponsor_e($c['category']) ?>" <?= $category===$c['category']?'selected':'' ?>><?= sponsor_e(ucwords(str_replace('_',' ',$c['category']))) ?></option><?php endforeach; ?></select></label><button class="sd-btn" type="submit">Apply filters</button><a class="sp-btn" href="<?= url('sponsor/documents.php') ?>">Clear</a></form>
<?php if(!$documents): ?><div class="sd-empty"><strong>No authorised documents found.</strong><p>Published reports and programme documents will appear here once programme management makes them available to your sponsor account.</p></div><?php else: ?><div class="sd-grid"><?php foreach($documents as $d): ?><article class="sd-card"><div class="sd-card-head"><div class="sd-file">▤</div><div><h2><?= sponsor_e($d['title']) ?></h2><p><?= sponsor_e($d['description']??'No description provided.') ?></p></div></div><div class="sd-meta"><span class="sd-tag"><?= sponsor_e(ucwords(str_replace('_',' ',$d['category']))) ?></span><span class="sd-tag"><?= sponsor_e(strtoupper($d['document_type'])) ?></span><span class="sd-tag"><?= (int)$d['version_count'] ?> version<?= (int)$d['version_count']===1?'':'s' ?></span></div><div class="sd-meta"><small style="color:var(--muted)">Programme: <?= sponsor_e($d['programme_names']) ?></small></div><div class="sd-foot"><small>Latest v<?= sponsor_e($d['latest_version']??'—') ?> · <?= sponsor_date($d['latest_published']??$d['updated_at']) ?></small><a class="sd-btn" href="<?= url('sponsor/document_download.php?id='.(int)$d['id']) ?>">Download</a></div></article><?php endforeach; ?></div><?php endif; ?><?php endif; ?>
<?php sponsor_footer(); ?>
